INSERT INTO mcq_questions (id, question, option_a, option_b, option_c, option_d, correct_answer, topic) VALUES
(26, 'Which of the following is NOT one of the four fundamental principles of Object-Oriented Programming (OOP) in Java?', 'Encapsulation', 'Compilation', 'Inheritance', 'Polymorphism', 'B', 'Core Java'),
(27, 'What is the effect of applying the ''final'' keyword to a variable in Java?', 'The variable can only be accessed within the same package', 'The variable''s value becomes constant and cannot be reassigned once initialized', 'The variable is automatically destroyed by the Garbage Collector', 'The variable can only store primitive numeric values', 'B', 'Core Java'),
(28, 'What is the difference between ''=='' and the ''.equals()'' method when comparing two String objects in Java?', '''=='' checks if values are equal, while ''.equals()'' checks memory addresses', '''=='' compares object memory references (addresses), while ''.equals()'' compares the actual text content', 'Both ''=='' and ''.equals()'' behave exactly the same for Strings', '''.equals()'' only works for primitive data types', 'B', 'Core Java'),
(29, 'Which Java Collection interface implementation stores key-value pairs and does NOT guarantee any specific ordering?', 'ArrayList', 'TreeSet', 'HashMap', 'LinkedList', 'C', 'Core Java'),
(30, 'In Java exception handling, which block is guaranteed to execute whether an exception occurs or not?', 'catch block', 'throw block', 'finally block', 'throws clause', 'C', 'Core Java'),
(31, 'What is the primary benefit of using Spring Boot compared to the traditional Spring Framework?', 'It eliminates the need to write Java code', 'It provides auto-configuration, embedded servers (like Tomcat), and starter dependencies for rapid development', 'It replaces HTML and JavaScript in frontend development', 'It only works with offline applications', 'B', 'Spring Boot'),
(32, 'Which annotation is used on a method in a Spring Boot controller to handle incoming HTTP GET requests?', '@GetMapping', '@PostMapping', '@ResponseBody', '@PutMapping', 'A', 'Spring Boot'),
(33, 'Which annotation is commonly used in Spring to automatically inject a dependency bean into another component?', '@Injectable', '@Autowired', '@Component', '@Repository', 'B', 'Spring Boot'),
(34, 'In RESTful web services, which HTTP status code indicates a successful request?', '404 Not Found', '500 Internal Server Error', '200 OK', '401 Unauthorized', 'C', 'Java Full Stack'),
(35, 'In Java Full Stack backend development, what does ''ORM'' stand for?', 'Object-Relational Mapping', 'Online Resource Management', 'Ordered Relationship Model', 'Open Routing Module', 'A', 'Java Full Stack'),
(36, 'In Spring Data JPA, which interface provides ready-to-use CRUD methods like save(), findById(), and deleteById()?', 'JpaRepository', 'HttpServlet', 'DataSource', 'EntityManagerFactory', 'A', 'Java Full Stack'),
(37, 'In the Model-View-Controller (MVC) architecture, what is the role of the Controller?', 'It represents the database tables and schemas directly', 'It displays the visual user interface to the client', 'It handles incoming HTTP requests, coordinates with service/model layers, and returns responses', 'It configures hardware networking ports', 'C', 'Java Full Stack'),
(38, 'Which Git command saves staged changes to your local repository along with a descriptive message?', 'git push', 'git commit -m "message"', 'git add .', 'git checkout', 'B', 'DevOps'),
(39, 'Which Git command downloads commits from a remote repository and immediately integrates them into your current local branch?', 'git pull', 'git clone', 'git init', 'git status', 'A', 'DevOps'),
(40, 'What is the plain text configuration file that contains the step-by-step instructions to create a Docker container image?', 'docker-compose.yml', 'Dockerfile', 'pom.xml', 'application.properties', 'B', 'DevOps'),
(41, 'Which Docker CLI command is used to list all currently running containers?', 'docker build', 'docker ps', 'docker stop', 'docker run', 'B', 'DevOps'),
(42, 'In Linux, which command is used to display the contents (files and directories) of the current folder?', 'pwd', 'cd', 'ls', 'mkdir', 'C', 'DevOps'),
(43, 'What does the acronym ''CI/CD'' stand for in DevOps methodology?', 'Central Integration / Cloud Deployment', 'Continuous Integration / Continuous Deployment (or Delivery)', 'Code Inspection / Continuous Distribution', 'Container Interface / Container Driver', 'B', 'DevOps'),
(44, 'Which widely used open-source automation tool is popular for building and managing automated CI/CD pipelines?', 'Jenkins', 'Eclipse IDE', 'Postman', 'MySQL Workbench', 'A', 'DevOps'),
(45, 'In an Apache Maven Java project, what is the primary configuration file that manages project dependencies, plugins, and build goals?', 'package.json', 'build.gradle', 'pom.xml', 'web.xml', 'C', 'DevOps')
